import './CrudButton.css';
import { useLocation, useNavigate } from 'react-router-dom';

// On the home page the button opens the compose form directly. No other page
// has a working compose form, so there the button goes home and asks
// HomeFeedPage to open it via router state (backlog #40).
export default function CrudButton(props) {
  const location = useLocation();
  const navigate = useNavigate();

  const pop_activities_form = (event) => {
    if (location.pathname === '/' && props.setPopped) {
      props.setPopped(true);
    } else {
      navigate('/', { state: { compose: true } });
    }
  }

  return (
    <button onClick={pop_activities_form} className='post'>Crud</button>
  );
}

import './HomeFeedPage.css';
import React from "react";
import { useLocation, useNavigate } from 'react-router-dom';

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ActivityFeed from '../components/ActivityFeed';
import ActivityForm from '../components/ActivityForm';
import ReplyForm from '../components/ReplyForm';        

import { signOut } from 'aws-amplify/auth';
import { checkAuth, getAccessToken } from '../components/lib/CheckAuth';

export default function HomeFeedPage() {
  const [activities, setActivities] = React.useState([]);
  const [popped, setPopped] = React.useState(false);
  const [poppedReply, setPoppedReply] = React.useState(false);
  const [replyActivity, setReplyActivity] = React.useState({});
  const [user, setUser] = React.useState(null);
  const location = useLocation();
  const navigate = useNavigate();

const loadData = async () => {
    console.log('loadData called');
    const headers = {};

    // Get a fresh access token (auto-refreshes if expired)
    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/home`;

    try {
      const res = await fetch(backend_url, {
        method: "GET",
        headers: headers,
      });

      const resJson = await res.json();
      if (res.status === 200) {
        setActivities(resJson)
      } else {
        console.log(res);
      }
    } catch (err) {
      console.log(err);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(() => {
    // This useEffect will run once when the component is mounted
    // to check the user's authentication status and then load data
    checkAuth(setUser);
    loadData();
  }, []);

  // The Crud button on any other page navigates here with { compose: true }
  // (backlog #40). Open the form, then clear the flag with a replace so a
  // refresh or Back does not reopen it.
  React.useEffect(() => {
    if (location.state && location.state.compose) {
      setPopped(true);
      navigate(location.pathname, { replace: true, state: {} });
    }
  }, [location.state, location.pathname, navigate]);

  React.useEffect(() => {
    // This effect runs whenever the `user` state changes
    // It will trigger loadData only after a user is authenticated
    if (user) {
      loadData(user);
    }
  }, [user]);

  return (
    <article>
      <DesktopNavigation user={user} active={'home'} setPopped={setPopped} handleSignOut={handleSignOut} />
      <div className='content'>
        <ActivityForm  
          popped={popped}
          setPopped={setPopped} 
          setActivities={setActivities} 
        />
        <ReplyForm 
          activity={replyActivity} 
          popped={poppedReply} 
          setPopped={setPoppedReply} 
          setActivities={setActivities} 
          activities={activities} 
        />
        <ActivityFeed 
          title="Home" 
          setReplyActivity={setReplyActivity} 
          setPopped={setPoppedReply} 
          activities={activities} 
        />
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}

