import './ReplyForm.css';
import React from "react";
import process from 'process';

import ActivityContent  from '../components/ActivityContent';
import { getAccessToken } from './lib/CheckAuth';

// Same limit the backend enforces (create_reply.py), counted in code points
// like Python's len() so an emoji counts as 1 (backlog #36).
const MAX_CHARS = 1024;

export default function ReplyForm(props) {
  const [count, setCount] = React.useState(0);
  const [message, setMessage] = React.useState('');
  const [error, setError] = React.useState(null);

  const setPopped = props.setPopped;

  const classes = []
  classes.push('count')
  if (MAX_CHARS-count < 0){
    classes.push('err')
  }

  // One exit point for every way the popup can close, so it never reopens
  // holding the previous attempt's text or error.
  const close = React.useCallback(() => {
    setCount(0);
    setMessage('');
    setError(null);
    setPopped(false);
  }, [setPopped]);

  // Escape closes. Only bound while the popup is open.
  React.useEffect(() => {
    if (props.popped !== true) return;
    const onKeyDown = (event) => {
      if (event.key === 'Escape') close();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [props.popped, close]);

  // Clicking the dimmed backdrop closes; clicking inside the dialog does not.
  const onBackdropClick = (event) => {
    if (event.target === event.currentTarget) close();
  };

  const onsubmit = async (event) => {
    event.preventDefault();
    setError(null);

    const headers = {
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    };

    // Every other fetch in this app sends a bearer token; this one did not.
    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    try {
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/${props.activity.uuid}/reply`
      const res = await fetch(backend_url, {
        method: "POST",
        headers: headers,
        body: JSON.stringify({ message: message }),
      });

      // Status before parse. A 502 from the ALB is HTML and a 401 can be empty;
      // res.json() throws SyntaxError on both and hides the real status.
      if (!res.ok) {
        const res_text_fallback = res.clone();
        let detail;
        try {
          detail = await res.json();
        } catch (json_err) {
          try {
            detail = await res_text_fallback.text();
          } catch (text_err) {
            detail = '';
          }
        }
        console.log('reply failed', res.status, detail);
        setError(`Could not post reply (${res.status}). Please try again.`);
        return;
      }

      const data = await res.json();

      const activities_deep_copy = JSON.parse(JSON.stringify(props.activities))
      const found_activity = activities_deep_copy.find(function (element) {
        return element.uuid === props.activity.uuid;
      });

      if (found_activity) {
        // home.sql does not return a replies array, so this must not assume
        // one exists. Pushing onto undefined was throwing into the outer catch
        // and leaving the popup open with no explanation.
        if (!Array.isArray(found_activity.replies)) {
          found_activity.replies = [];
        }
        found_activity.replies.push(data)
        props.setActivities(activities_deep_copy);
      }

      close();
    } catch (err) {
      console.log(err);
      setError('Could not post reply. Please try again.');
    }
  }

  const textarea_onchange = (event) => {
    setCount(Array.from(event.target.value).length);
    setMessage(event.target.value);
  }

  let content;
  if (props.activity){
    content = <ActivityContent activity={props.activity} />;
  }

  if (props.popped === true) {
    return (
      <div className="popup_form_wrap" onClick={onBackdropClick}>
        <div className="popup_form">
          <div className="popup_heading">
            <div className="popup_title">Reply</div>
            <div
              className="popup_close"
              onClick={close}
              role="button"
              tabIndex={0}
              aria-label="Close"
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') close(); }}
            >&times;</div>
          </div>
          <div className="popup_content">
            <div className="activity_wrap">
              {content}
            </div>
            {error && <div className='errors'>{error}</div>}
            <form
              className='replies_form'
              onSubmit={onsubmit}
            >
              <textarea
                type="text"
                placeholder="what is your reply?"
                value={message}
                onChange={textarea_onchange}
              />
              <div className='submit'>
                <div className={classes.join(' ')}>{MAX_CHARS-count}</div>
                <button type='submit'>Reply</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return null;
}

import './MessageForm.css';
import React from "react";
import process from 'process';
import { useParams } from 'react-router-dom';
import { getAccessToken } from './lib/CheckAuth';

export default function MessageForm(props) {
  const [count, setCount] = React.useState(0);
  const [message, setMessage] = React.useState('');
  const params = useParams();

  const classes = []
  classes.push('count')
  if (1024-count < 0){
    classes.push('err')
  }

   const onsubmit = async (event) => {
    event.preventDefault();

    const headers = {
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    };

    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }



    try {
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/messages`
      console.log('onsubmit payload', message)

      // Build the request body
      let json = { 'message': message }
      if (params.handle) {
        json.handle = params.handle  // ✅ Match backend
      } else {
        json.message_group_uuid = params.message_group_uuid
      }

      const res = await fetch(backend_url, {
        method: "POST",
        headers: headers,
        body: JSON.stringify(json)
      });

      // Check the status BEFORE touching the body. A 502 from the ALB is HTML,
      // a 401 can be empty, and a Flask traceback is neither: res.json() throws
      // a SyntaxError on all three, which used to escape to the outer catch.
      if (!res.ok) {
        // res.json() consumes the body, so a clone is kept for the text fallback.
        const res_text_fallback = res.clone();
        let detail;
        try {
          detail = await res.json();
        } catch (json_err) {
          try {
            detail = await res_text_fallback.text();
          } catch (text_err) {
            detail = '';
          }
        }
        // TODO: surface this failure to the user. This component has no
        // error-display mechanism (no errors state, no shared FormErrors
        // component, no toast), and there is none elsewhere in the app to
        // reuse, so wiring (c) up would mean inventing new UI. Until that
        // exists the send fails silently: the textarea keeps its text and
        // nothing appears on screen.
        console.log('message send failed', res.status, detail)
        return
      }

      let data = await res.json();
      console.log('data:', data)

      // If backend returns a message_group_uuid, it's a new conversation - redirect
      if (data.message_group_uuid) {
        console.log('redirect to message group')
        window.location.href = `/messages/${data.message_group_uuid}`
      } else {
        // Otherwise, update the existing conversation
        props.setMessages(current => [...current, data]);
        setMessage(''); // Clear the input after sending
        setCount(0); // Reset character count
      }
    } catch (err) {
      console.log(err);
    }
  }

  const textarea_onchange = (event) => {
    // Code points, like Python's len() in create_message.py (backlog #36).
    setCount(Array.from(event.target.value).length);
    setMessage(event.target.value);
  }

  return (
    <form 
      className='message_form'
      onSubmit={onsubmit}
    >
      <textarea
        type="text"
        placeholder="send a direct message..."
        value={message}
        onChange={textarea_onchange} 
      />
      <div className='submit'>
        <div className={classes.join(' ')}>{1024-count}</div>
        <button type='submit'>Message</button>
      </div>
    </form>
  );
}

import './ProfileForm.css';
import React from "react";
import process from 'process';
import { getAccessToken } from '../components/lib/CheckAuth';

export default function ProfileForm(props) {
  const [bio, setBio] = React.useState('');
  const [displayName, setDisplayName] = React.useState('');
  // Visible result of a photo upload (backlog #33); it used to go to the
  // console only, so a user could not tell whether anything happened.
  const [uploadStatus, setUploadStatus] = React.useState(null);

  React.useEffect(() => {
    if (props.profile) {
      setBio(props.profile.bio || '');
      setDisplayName(props.profile.display_name || '');
    }
  }, [props.profile]);

  const onsubmit = async (event) => {
    event.preventDefault();
    const accessToken = await getAccessToken();
    try {
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/profile/update`;
      const res = await fetch(backend_url, {
        method: "POST",
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${accessToken}`
        },
        body: JSON.stringify({
          bio: bio,
          display_name: displayName
        }),
      });
      let data = await res.json();
      if (res.status === 200) {
        await props.loadData();
        props.setPopped(false);
      } else {
        console.log(res);
      }
    } catch (err) {
      console.log(err);
    }
  };

  const s3_upload_key = async (extension) => {
    const gateway_url = `${process.env.REACT_APP_API_GATEWAY_ENDPOINT_URL}/avatars/key_upload`;
    const accessToken = await getAccessToken();
    try {
      const res = await fetch(gateway_url, {
        method: "POST",
        headers: {
          'Authorization': `Bearer ${accessToken}`,
          'Accept': 'application/json',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ extension: extension })
      });
      let data = await res.json();
      return data.url;
    } catch (err) {
      console.log(err);
    }
  };

  const s3_upload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const filename = file.name;
    const extension = filename.split('.').pop();
    setUploadStatus('Uploading…');
    const presignedUrl = await s3_upload_key(extension);
    if (!presignedUrl) {
      setUploadStatus('Upload failed: could not get an upload link. Please try again.');
      return;
    }

    try {
      const res = await fetch(presignedUrl, {
        method: "PUT",
        body: file,
        headers: {
          'Content-Type': file.type
        }
      });
      if (res.status === 200) {
        console.log('Avatar uploaded successfully');
        setUploadStatus('Photo uploaded. It can take a minute to appear. Refresh the page to see it.');
      } else {
        console.log('Upload failed:', res);
        setUploadStatus(`Upload failed (${res.status}). Please try again.`);
      }
    } catch (err) {
      console.log(err);
      setUploadStatus('Upload failed. Please try again.');
    }
  };

  const bio_onchange = (event) => {
    setBio(event.target.value);
  };

  const display_name_onchange = (event) => {
    setDisplayName(event.target.value);
  };

  const close = (event) => {
    if (event) event.preventDefault();
    setUploadStatus(null);
    props.setPopped(false);
  };

  if (props.popped === true) {
    return (
      <div className="popup_form_wrap">
        <div className="popup_form">
          <div className="popup_heading">
            <div className="popup_title">Edit Profile</div>
            <div className='popup_close' onClick={close}>X</div>
          </div>
          <div className="popup_content">
            <div className="field">
              <label>Display Name</label>
              <input
                type="text"
                placeholder="Display Name"
                value={displayName}
                onChange={display_name_onchange}
              />
            </div>
            <div className="field">
              <label>Bio</label>
              <textarea
                placeholder="Bio"
                value={bio}
                onChange={bio_onchange}
              />
            </div>
            <div className="field">
              <label>Avatar</label>
              <input
                type="file"
                accept="image/jpeg,image/png"
                onChange={s3_upload}
              />
              {uploadStatus && (
                <div
                  className='upload_status'
                  style={{ marginTop: '8px', fontSize: '14px', color: 'rgba(255,255,255,0.7)' }}
                >
                  {uploadStatus}
                </div>
              )}
            </div>
            <div className='submit'>
              <button onClick={onsubmit}>Save</button>
            </div>
          </div>
        </div>
      </div>
    );
  }
}
